    <style>
        body {
            font-family: 'Bricolage Grotesque';
            background-color: #f3f3f3;
        }

        /* Styling for the Google Translate container to ensure proper layout */
        #google_translate_element {
            /* Keep this as a flex container to center its internal elements */
            display: flex;
            align-items: center;
            height: 25px;
            /* Explicit height to match your header line-height */
            overflow: hidden;
            /* Hide anything that overflows, like default border */
        }

        /* Target the main Google Translate dropdown button */
        .goog-te-gadget-simple {
            border: none !important;
            /* Remove default border */
            background-color: transparent !important;
            /* Make background transparent */
            padding: 0 !important;
            /* Remove default padding */
            line-height: inherit !important;
            /* Inherit line-height for better alignment */
            font-size: 15px !important;
            /* Match your other text size */
            display: flex !important;
            /* Make it a flex container */
            align-items: center !important;
            /* Vertically align its contents */
            white-space: nowrap;
            /* Prevent wrapping */
        }

        /* Target the selected language text within the dropdown */
        .goog-te-gadget-simple .goog-te-menu-value {
            color: black !important;
            /* Ensure text color is black */
            font-size: 15px !important;
            /* Ensure consistent font size */
            margin-right: 5px;
            /* Space between text and arrow */
            text-decoration: none !important;
            /* Remove underline */
        }

        /* Target the dropdown arrow */
        .goog-te-gadget-simple .goog-te-menu-value span:nth-child(3) {
            /* This targets the span that usually contains the arrow icon */
            vertical-align: middle !important;
            /* Try to vertically align it */
            position: relative !important;
            /* Needed for top/transform if used */
            top: 1px;
            /* Adjust as needed for fine-tuning vertical alignment */
        }

        /* Target the 'Powered by' link if it's not hidden */
        .goog-te-gadget-simple a {
            text-decoration: none !important;
            /* Remove underline from the link */
        }

        /* To hide the "Powered by Google Translate" text if desired */
        .VIpgJd-ZVi9od-ORHb-OEVm-DESE-ruf5o.VIpgJd-ZVi9od-ORHb-OEVm-DESE-ruf5o,
        .VIpgJd-ZVi9od-aVgMtb-eHVCOe,
        .goog-tooltip,
        .goog-tooltip:hover,
        .goog-text-highlight {
            display: none !important;
            background-color: transparent !important;
            box-shadow: none !important;
        }

        /* Ensure the translate iframe itself doesn't cause overflow */
        .skiptranslate.goog-te-gadget {
            line-height: initial !important;
            /* Reset line-height if it's inherited poorly */
        }
    </style>
    <script type="text/javascript">
        function googleTranslateElementInit() {
            new google.translate.TranslateElement({
                pageLanguage: 'en',
                includedLanguages: 'en,bn,fr',
                layout: google.translate.TranslateElement.InlineLayout.SIMPLE
            }, 'google_translate_element');
        }
    </script>
    <script src="//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit"></script>

