<body>
    <!-- Topbar -->
    <section class="h-10 bg-[#dcdcdc70] py-2 border-b-2 border-b-[#dcdcdc4a] lg:block hidden">
        <div class="max-w-[1100px] h-full flex items-center justify-between mx-auto">
            <div class="flex items-center gap-1 text-[15px]">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5"
                    stroke="currentColor" class="size-5">
                    <path stroke-linecap="round" stroke-linejoin="round"
                        d="M2.25 6.75c0 8.284 6.716 15 15 15h2.25a2.25 2.25 0 0 0 2.25-2.25v-1.372c0-.516-.351-.966-.852-1.091l-4.423-1.106c-.44-.11-.902.055-1.173.417l-.97 1.293c-.282.376-.769.542-1.21.38a12.035 12.035 0 0 1-7.143-7.143c-.162-.441.004-.928.38-1.21l1.293-.97c.363-.271.527-.734.417-1.173L6.963 3.102a1.125 1.125 0 0 0-1.091-.852H4.5A2.25 2.25 0 0 0 2.25 4.5v2.25Z" />
                </svg>
                <span>
                    Have a question? Call us <a href="tel:+88019 111 222 52" class="hover:underline"> 01911-122252</a>
                </span>
            </div>
            <div class="flex items-center gap-2">
                <a href="#">Sign In</a>
                <span style="margin:4px 5px;height: 15px;display: inline-block;width: 1px;background: black;"></span>
                <a href="#">Sign Up</a>
                <div>
                    <a href="#seller" class="border py-[2px] px-2 rounded-lg">Seller</a>
                </div>
                <div id="google_translate_element_wrapper" class="ml-2">
                    <div id="google_translate_element"></div>
                </div>
            </div>
        </div>
    </section>

    <!-- header -->
    <section
        class=" hidden lg:block sticky top-0 z-[100] bg-[#f3f3f3] py-2.5 border-b-[0.5px] sm:min-h-[110px] border-b-[#f3f3f3] transition-all duration-300 shadow-md">
        <div class="max-w-[1100px] mx-auto px-4">
            <div class="flex items-center justify-center gap-10">
                <a href="{{ route('new.home')}}">
                    <img src="https://ettabashop.com/assets/images/logo/logo.png" alt="Ettaba Shop Logo" width="120">
                </a>
                <div class="w-full mt-5">
                    <form action="#"
                        class="flex h-[45px] bg-white border border-gray-200 rounded-lg shadow-sm overflow-hidden">
                        <input id="searchInput" type="text" placeholder="Search by Vendor"
                            class="w-full h-full px-4 py-2 text-sm text-gray-700 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#007025] transition-all" />
                        <button type="submit"
                            class="bg-[#007025] px-4 flex items-center justify-center hover:bg-[#005d1d] transition-colors">
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5"
                                stroke="#fff" class="w-5 h-5">
                                <path stroke-linecap="round" stroke-linejoin="round"
                                    d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z" />
                            </svg>
                        </button>
                    </form>
                </div>

                <div class="flex justify-center items-center gap-3 mt-5">
                    <div class="flex justify-center items-center gap-1">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5"
