        </div>
    </section>

    <!-- navbar -->
    <section class="h-12 bg-[#007025] hidden lg:block">
        <div class="max-w-[1100px] h-full flex items-center justify-start mx-auto gap-5 px-4 sm:px-0">
            <!-- <div
                class="relative group h-12 inline-flex items-center justify-between bg-[#0000004d] text-white text-[16px] px-4 font-semibold gap-2 cursor-pointer w-[240px]"> -->
            <div 
    class="relative group h-12 inline-flex items-center justify-between bg-[#0000004d] text-white text-[16px] px-4 font-semibold gap-2 cursor-pointer w-[240px]"
    x-data="{
        show: false,
        isHome: {{ Route::is('new.home') ? 'true' : 'false' }},
        init() {
            this.handleResize();
            window.addEventListener('resize', this.handleResize.bind(this));
        },
        handleResize() {
            if (this.isHome) {
                this.show = window.innerWidth > 1100;
            }
        },
        handleMouseEnter() {
            if (!this.isHome) this.show = true;
        },
        handleMouseLeave() {
            if (!this.isHome) this.show = false;
        },
        handleClickOutside() {
            if (!this.isHome) this.show = false;
        }
    }"
    @mouseenter="handleMouseEnter"
    @mouseleave="handleMouseLeave"
>

                <!-- Left side: Menu Icon + Text -->
                <div class="flex items-center gap-2">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="current" viewBox="0 0 24 24" stroke-width="1.5"
                        stroke="currentColor" class="w-5 h-5">
