    <script>
        document.addEventListener('DOMContentLoaded', function () {
            new Glide('.glide', {
                type: 'carousel',
                startAt: 0,
                perView: 1,
                autoplay: 4000,
                hoverpause: true,
                animationDuration: 800
            }).mount();
        });

        // typer 
        const input = document.getElementById('searchInput');
        const texts = ["Search by Vendor", "Search by Product", "Search by Sellers"];
        let textIndex = 0;
        let charIndex = 0;
        let typing = true;

        function typePlaceholder() {
            if (typing) {
                if (charIndex < texts[textIndex].length) {
                    input.placeholder += texts[textIndex].charAt(charIndex);
                    charIndex++;
                    setTimeout(typePlaceholder, 100);
                } else {
                    typing = false;
                    setTimeout(typePlaceholder, 1500); // pause after typing
                }
            } else {
                if (charIndex > 0) {
                    input.placeholder = input.placeholder.slice(0, -1);
                    charIndex--;
                    setTimeout(typePlaceholder, 50);
                } else {
                    typing = true;
                    textIndex = (textIndex + 1) % texts.length;
                    setTimeout(typePlaceholder, 500);
                }
            }
        }

        input.placeholder = '';
        typePlaceholder();
    </script>

    @if (config('app.env') === 'local')
